<div class="adm-table-wrap" style="background:#fff;border:1px solid #ececec;border-radius:12px"><table class="tcm-table"><thead><tr><th>Partner course</th><th>Institution</th><th>Fee</th><th>Status</th><th>Review</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="5">No submitted partner courses.</td></tr><?php endif ?><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['title']) ?></strong><br><?= e($r['description']??'') ?></td><td><?= e($r['display_name']) ?></td><td><?= $r['current_fee']!==null?'₹'.number_format((float)$r['current_fee'],2):'—' ?></td><td><?= e(str_replace('_',' ',$r['review_status'])) ?></td><td><form method="post" action="<?= base_url('/admin/partners/courses/'.$r['id']) ?>"><?= csrf_field() ?><select class="form-select form-select-sm" name="status"><option value="approved">Approve</option><option value="rejected">Reject</option><option value="unpublished">Unpublish</option></select><input class="form-control form-control-sm mt-1" name="reason" placeholder="Rejection reason if needed"><button class="tcm-btn primary sm mt-1">Save</button></form></td></tr><?php endforeach ?></tbody></table></div>
